#!/usr/bin/env bash
# Nova Hub deploy (generated by tools/build-hub.js). Pulls hub/ from the public GitHub repo at build time
# and verifies every file against the checksums below, so the site is byte-for-byte what is in git.
set -euo pipefail
BASE="https://raw.githubusercontent.com/shanemichael631-code/READ-ME-/claude/gifted-edison-7f7zwz/hub"
mkdir -p public
for f in index.html manifest.webmanifest apple-touch-icon.png icon-192.png icon-512.png icon-192-maskable.png icon-512-maskable.png; do
  curl -fsSL "$BASE/$f?nocache=$(date +%s)" -o "public/$f"
done
cd public
sha1sum -c <<'SUMS'
7222483cd0d35bdd019d85e8523ca88b5b85d298  index.html
62b5d59052a46afadde6ff9d67fad0f26b734217  manifest.webmanifest
80e05a687c4368950d2af243f30d9e786070ef03  apple-touch-icon.png
6cbe2af5829c538d6aa9d649ae9a3a85d0916232  icon-192.png
31ba8cb3a81c20fd9c53c715edffe4df58aa7f0e  icon-512.png
0eea131a9daec618819f4519e41a7bcd9bf3f087  icon-192-maskable.png
f33104efea19dfa1f41786480c7c19c050e72519  icon-512-maskable.png
SUMS
ls -la
